function executeSkill(context) {
  if (context.statusId !== 'divine-shield') return { success: false, message: '' };
  var sourcePiece = context.sourcePiece || context.piece;
  if (!sourcePiece) return { success: false, message: '' };
  var bound = context.rulePiece;
  var liadrin = bound && battle.pieces.find(function(piece) { return piece.instanceId === bound.instanceId && piece.templateId === 'liadrin' && piece.currentHp > 0; });
  if (!liadrin || !arePlayersAllied(battle, liadrin.ownerPlayerId, sourcePiece.ownerPlayerId)) return { success: false, message: '' };
  if (!liadrin) return { success: false, message: '' };
  var player = battle.players.find(function(item) { return item.playerId === liadrin.ownerPlayerId; });
  if (!player) return { success: false, message: '' };
  var added = addCardToHand('holy-charge', player.playerId);
  return { success: added, message: added ? '血色回响生成了1张圣光充能' : '' };
}
